import"./chunk-2NFLSA4Y.js";var o={higgs:{theory:{concept:"[[The Higgs field is a field that fills all of space; elementary particles such as quarks, the electron and the W and Z bosons get their mass by interacting with it.]] The more strongly a particle interacts with the field, the larger its mass: the top quark interacts the most, the electron very little, and the photon not at all \u2014 so the photon has no mass and always travels at the speed of light. At the same energy a heavier particle moves more slowly."},section:{standardModel:{title:"The Standard Model",text:"Our best theory of the smallest building blocks. It describes 12 matter particles, 4 kinds of force-carrying particles and the Higgs boson."},matter:{title:"Matter: quarks and leptons",text:"Quarks (up, down, \u2026, top) build protons and neutrons: a proton is two up quarks and one down quark. Leptons include the electron. Quarks are never found alone."},forces:{title:"Force carriers (bosons)",text:"Forces are passed on by particles: the photon (electromagnetism, light), the gluon (holds quarks together), and the W and Z bosons (the weak force, radioactivity)."},boson:{title:"The Higgs boson",text:"If you hit the Higgs field hard enough, it ripples. Such a ripple is a particle \u2014 the Higgs boson, mass 125 GeV/c\xB2. It lives only 10\u207B\xB2\xB2 s and immediately turns into other particles."},discovery:{title:"Discovery (2012)",text:"The Large Hadron Collider at CERN smashed protons together billions of times. In 2012 scientists found the Higgs boson, often by its decay into two photons. Peter Higgs and Fran\xE7ois Englert, who predicted it in 1964, received the Nobel Prize in 2013. Since then the LHC has measured its mass precisely (125.1 GeV/c\xB2) and seen it interact with the top and bottom quarks, the tau lepton and the W and Z bosons just as strongly as the Standard Model predicts."},ownMass:{title:"Is all mass from the Higgs?",text:"No! [[The Higgs field gives mass to quarks and electrons, but about 99 % of your mass comes from the energy of the strong force that binds quarks inside protons and neutrons (E = m\xB7c\xB2).]]"}},formula:{einstein:"Energy and mass are equivalent",speed:"Speed of a particle with energy E (special relativity)",gamma:"Lorentz factor",yukawa:"Mass of a quark or lepton from its Higgs coupling y",decay:"Energy is conserved when the Higgs boson decays"},variable:{c:"Speed of light (3 \xB7 10\u2078 m/s)",v:"Speed of the particle"},assumption:{analogy:"The field \u201Cgathering\u201D around particles is a picture to help imagine the interaction \u2014 the Higgs field does not slow particles down like friction.",scale:"Distances and times are scaled for the screen; the speeds (as fractions of c) are calculated correctly.",quarks:"Quarks are never found alone; single quarks are shown only to compare their masses.",lifetime:"The Higgs boson really lives about 1.6 \xB7 10\u207B\xB2\xB2 s; the animation slows this down enormously.",collision:"In a real collision quarks and gluons inside the protons collide, and many other particles are created as well."},param:{mode:"Experiment",particle:"Particle",energy:"Particle energy",decay:"Decay of the Higgs boson"},hint:{particle:"Compare a light particle with a heavy one.",energy:"A particle needs at least E = m\xB7c\xB2 to exist.",decay:"Two photons are rare but easy to spot \u2014 that is how the Higgs was found."},mode:{field:"Race through the Higgs field",collider:"Collider: create a Higgs boson"},option:{photon:"Photon \u03B3 (0)",electron:"Electron e\u207B (0.0005 GeV)",muon:"Muon \u03BC\u207B (0.106 GeV)",up:"Up quark u (0.002 GeV)",down:"Down quark d (0.005 GeV)",bottom:"Bottom quark b (4.18 GeV)",w:"W boson (80.4 GeV)",z:"Z boson (91.2 GeV)",higgs:"Higgs boson H (125 GeV)",top:"Top quark t (172.6 GeV)"},decayOption:{photons:"H \u2192 \u03B3\u03B3 (two photons)",bottom:"H \u2192 b b\u0304 (two bottom quarks)"},particle:{photon:"photon",electron:"electron",muon:"muon",up:"up quark",down:"down quark",bottom:"bottom quark",w:"W boson",z:"Z boson",higgs:"Higgs boson",top:"top quark"},measure:{mass:"Mass",energy:"Energy",gamma:"Lorentz factor",coupling:"Higgs interaction (top quark = 1)",kineticEnergy:"Kinetic energy",speedFraction:"Speed (fraction of light)",crossingRatio:"Time compared with light (\xD7)",higgsMass:"Higgs boson mass",productEnergy:"Energy of each product",branching:"Share of decays"},view:{finish:"finish",mass:"rest energy m\xB7c\xB2 = {mass}",notEnoughEnergy:"Not enough energy: this particle needs at least {mass}",fieldAnalogy:"Dots = the Higgs field (picture, not to scale)",protonsApproach:"Two protons fly towards each other at almost the speed of light",higgsCreated:"A Higgs boson is created \u2014 a ripple in the Higgs field",decay:{photons:"It decays into two photons ({percent} % of decays)",bottom:"It decays into a bottom quark and antiquark ({percent} % of decays)"},colliderNote:"Slowed down ~10\xB2\xB2 times \xB7 not to scale"},challenge:{race:{title:"Almost as fast as light",description:"Race a particle (not the photon) that arrives practically together with light (within 0.1 %).",hint:"Particles with a tiny mass barely notice the Higgs field."},heaviest:{title:"The heavyweight",description:"Send the heaviest known elementary particle across the field.",hint:"It is a quark, as heavy as a gold atom."},energy:{title:"Too heavy to make",description:"Choose an energy that is too small to create the chosen particle.",hint:"A particle needs at least E = m\xB7c\xB2. Try the top quark with less than 173 GeV."},half:{title:"Half the speed of light",description:"Make a particle move at half the speed of light (v/c = 0.5 \xB1 0.01).",hint:"v = 0.5c when E \u2248 1.155 \xD7 m\xB7c\xB2. For the top quark that is about 199 GeV."},discovery:{title:"Discover the Higgs",description:"Run the collider and watch a Higgs boson decay into two photons \u2014 like CERN in 2012.",hint:"Choose the collider experiment and the two-photon decay, then press Play."}}}},a={sim:o};export{a as default,o as sim};
